import { NextResponse } from "next/server";
import { requireStorefrontAdmin } from "@/lib/adminRouteAuth";

const ORDER_SELECT = `
  id,
  store_id,
  seller_id,
  user_id,
  status,
  payout_status,
  total_amount,
  currency_code,
  origin_channel,
  checkout_mode,
  is_guest_checkout,
  customer_name,
  guest_name,
  guest_email,
  guest_phone,
  payment_reference,
  created_at,
  updated_at,
  buyer:profiles!orders_user_id_fkey ( id, email, full_name, display_name, phone_number ),
  seller:profiles!orders_seller_id_fkey ( id, email, full_name, display_name, slug )
`;

export async function GET(request: Request) {
  const gate = await requireStorefrontAdmin();
  if (!gate.ok) return gate.response;

  const { searchParams } = new URL(request.url);
  const limit = Math.min(Math.max(Number(searchParams.get("limit") || 50), 1), 150);
  const offset = Math.max(Number(searchParams.get("offset") || 0), 0);
  const origin = searchParams.get("origin")?.trim().toLowerCase();
  const status = searchParams.get("status")?.trim();
  const q = searchParams.get("q")?.trim() ?? "";

  let query = gate.svc.from("orders").select(ORDER_SELECT, { count: "exact" }).order("created_at", { ascending: false });

  if (origin && origin !== "all") {
    if (!["storefront", "web_app", "mobile_app", "admin"].includes(origin)) {
      return NextResponse.json({ error: "Invalid origin filter" }, { status: 400 });
    }
    query = query.eq("origin_channel", origin);
  }

  if (status && status !== "all") {
    query = query.eq("status", status);
  }

  if (q) {
    const uuidLike = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(q);
    if (uuidLike) {
      query = query.eq("id", q);
    } else {
      const safe = q.replace(/%/g, "");
      const pat = `%${safe}%`;
      query = query.or(
        `customer_name.ilike.${pat},guest_email.ilike.${pat},guest_name.ilike.${pat},payment_reference.ilike.${pat}`,
      );
    }
  }

  query = query.range(offset, offset + limit - 1);

  const { data, error, count } = await query;
  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }

  const rows = data ?? [];
  const storeIds = [...new Set(rows.map((o: { store_id?: string | null }) => o.store_id).filter(Boolean))] as string[];
  let storeMap: Record<string, { name: string | null; slug: string | null }> = {};
  if (storeIds.length > 0) {
    const { data: stores } = await gate.svc.from("stores").select("id,name,slug").in("id", storeIds);
    for (const s of stores || []) {
      storeMap[s.id] = { name: s.name, slug: s.slug };
    }
  }

  const orders = rows.map((o: { store_id?: string | null }) => ({
    ...o,
    store: o.store_id ? storeMap[o.store_id] ?? null : null,
  }));

  return NextResponse.json({ orders, total: count ?? orders.length, limit, offset });
}
